/**
 * TASK: Turn pixel coordinates into board cells.
 *
 * The board is 4 columns by 3 rows of 25-pixel cells, and its top-left
 * corner sits at (10, 5). So the board covers x from 10 up to (not
 * including) 110 and y from 5 up to (not including) 80.
 *
 * 1. cellAt(x, y) returns "<row>,<col>" for a point on the board, for
 *    example "0,0" for (12, 8) and "2,3" for (109, 79). For any point off
 *    the board it returns "none".
 *
 *    EDGE CASE: test the bounds BEFORE dividing. Java truncates towards
 *    zero, so (5 - 10) / 25 is 0, not -1, and a click just to the left of
 *    the board would otherwise look like column 0.
 *
 * 2. Register a MouseListener whose mouseClicked toggles the clicked cell
 *    (a filled cell becomes empty and an empty one becomes filled), ignores
 *    clicks off the board, and sets the label named "cell" to whatever
 *    cellAt returned for that click.
 *
 * isFilled(row, col) and filledCount() report the board state; the label
 * starts as "none".
 *
 * No window is ever opened -- the tests build MouseEvents by hand and hand
 * them to the panel with dispatchEvent.
 */
import javax.swing.JLabel;
import javax.swing.JPanel;

public class GridCellPicker extends JPanel {

    static final int LEFT = 10;
    static final int TOP = 5;
    static final int CELL = 25;
    static final int COLS = 4;
    static final int ROWS = 3;

    private final JLabel cellLabel = new JLabel("none");
    private final boolean[][] filled = new boolean[ROWS][COLS];

    public GridCellPicker() {
        cellLabel.setName("cell");
        add(cellLabel);
        // TODO: addMouseListener(...) -- on mouseClicked use cellAt to find the
        // TODO: cell, toggle it when there is one, and update the label
    }

    public String cellAt(int x, int y) {
        // TODO: "row,col" for a point on the board, otherwise "none"
        return "";
    }

    public boolean isFilled(int row, int col) {
        return filled[row][col];
    }

    public int filledCount() {
        int total = 0;
        for (boolean[] rowCells : filled) {
            for (boolean cell : rowCells) {
                if (cell) {
                    total++;
                }
            }
        }
        return total;
    }
}

