public class GridCellPickerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.awt.Component find(java.awt.Container root, String name) {
        if (name.equals(root.getName())) {
            return root;
        }
        for (java.awt.Component child : root.getComponents()) {
            if (name.equals(child.getName())) {
                return child;
            }
            if (child instanceof java.awt.Container) {
                java.awt.Component result = find((java.awt.Container) child, name);
                if (result != null) {
                    return result;
                }
            }
        }
        return null;
    }

    static String textOf(java.awt.Component c) {
        if (c instanceof javax.swing.JLabel) {
            return ((javax.swing.JLabel) c).getText();
        }
        if (c instanceof javax.swing.text.JTextComponent) {
            return ((javax.swing.text.JTextComponent) c).getText();
        }
        return "(missing)";
    }

    static void click(GridCellPicker panel, int x, int y) {
        panel.dispatchEvent(new java.awt.event.MouseEvent(panel,
                java.awt.event.MouseEvent.MOUSE_CLICKED, System.currentTimeMillis(),
                0, x, y, 1, false));
    }

    public static void main(String[] args) {
        try {
            GridCellPicker panel = new GridCellPicker();
            java.awt.Component label = find(panel, "cell");

            check("top-left pixel of the board", "0,0", panel.cellAt(10, 5));
            check("a point inside the first cell", "0,0", panel.cellAt(12, 8));
            check("the last cell", "2,3", panel.cellAt(109, 79));
            check("just left of the board", "none", panel.cellAt(5, 8));
            check("just past the right edge", "none", panel.cellAt(110, 8));
            check("just above the board", "none", panel.cellAt(12, 4));
            check("just below the board", "none", panel.cellAt(12, 80));

            click(panel, 12, 8);
            check("clicking fills a cell", true, panel.isFilled(0, 0));
            check("label after the click", "0,0", textOf(label));

            click(panel, 20, 20);
            check("clicking the same cell again empties it", 0, panel.filledCount());

            click(panel, 60, 60);
            click(panel, 100, 10);
            check("two different cells are filled", 2, panel.filledCount());
            check("row and column of a middle click", true, panel.isFilled(2, 2));

            click(panel, 200, 200);
            check("an off-board click changes nothing", 2, panel.filledCount());
            check("label after an off-board click", "none", textOf(label));
        } catch (Throwable t) {
            System.out.println("FAIL  unexpected problem -- " + t);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

