import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.JLabel;
import javax.swing.JPanel;

public class GridCellPicker extends JPanel {

    static final int LEFT = 10;
    static final int TOP = 5;
    static final int CELL = 25;
    static final int COLS = 4;
    static final int ROWS = 3;

    private final JLabel cellLabel = new JLabel("none");
    private final boolean[][] filled = new boolean[ROWS][COLS];

    public GridCellPicker() {
        cellLabel.setName("cell");
        add(cellLabel);
        addMouseListener(new MouseAdapter() {
            @Override
            public void mouseClicked(MouseEvent e) {
                String cell = cellAt(e.getX(), e.getY());
                if (!cell.equals("none")) {
                    int comma = cell.indexOf(',');
                    int row = Integer.parseInt(cell.substring(0, comma));
                    int col = Integer.parseInt(cell.substring(comma + 1));
                    filled[row][col] = !filled[row][col];
                }
                cellLabel.setText(cell);
            }
        });
    }

    public String cellAt(int x, int y) {
        if (x < LEFT || x >= LEFT + COLS * CELL) {
            return "none";
        }
        if (y < TOP || y >= TOP + ROWS * CELL) {
            return "none";
        }
        int col = (x - LEFT) / CELL;
        int row = (y - TOP) / CELL;
        return row + "," + col;
    }

    public boolean isFilled(int row, int col) {
        return filled[row][col];
    }

    public int filledCount() {
        int total = 0;
        for (boolean[] rowCells : filled) {
            for (boolean cell : rowCells) {
                if (cell) {
                    total++;
                }
            }
        }
        return total;
    }
}
